from aerelith.core.result import Result

def top_by_weight(rows, *, k):
    """Return the k highest-weight rows, sorted by weight descending.

    Args:
        rows: List of dicts with 'id' and 'weight' keys
        k: Number of rows to return (must be 1..len(rows))

    Returns:
        Result containing the top k rows sorted by weight
    """
    if not rows:
        return Result(ok=False, value=None, err=E_EMPTY)

    if k < 1 or k > len(rows):
        return Result(ok=False, value=None, err=E_RANGE)

    sorted_rows = sorted(rows, key=lambda r: r.get("weight", 0), reverse=True)
    out = sorted_rows[:k]
    return Result(ok=True, value=out, err=None)
