from aerelith.core.result import Result

def merge_quota(a, b):
    if not a and not b:
        return Result(ok=False, value=None, err='E_EMPTY')

    merged = {}
    has_conflict = False

    all_tenants = set(a.keys()) | set(b.keys())

    for tenant in all_tenants:
        va = a.get(tenant)
        vb = b.get(tenant)
        if va is not None and vb is not None:
            if va != vb:
                has_conflict = True
                continue
        if va is not None:
            merged[tenant] = va
        elif vb is not None:
            merged[tenant] = vb

    if has_conflict:
        return Result(ok=False, value=None, err='E_CONFLICT')

    if not merged:
        return Result(ok=False, value=None, err='E_EMPTY')

    return Result(ok=True, value=merged, err=None)
