def parse_window(spec):
    if not spec:
        return Result(ok=False, value=None, err='E_EMPTY')
    if len(spec) < 2:
        return Result(ok=False, value=None, err='E_RANGE')
    unit = spec[-1]
    num_str = spec[:-1]
    if unit not in ('d', 'h', 'm'):
        return Result(ok=False, value=None, err='E_RANGE')
    if not num_str.isdigit():
        return Result(ok=False, value=None, err='E_RANGE')
    num = int(num_str)
    if num <= 0:
        return Result(ok=False, value=None, err='E_RANGE')
    if unit == 'd':
        return Result(ok=True, value=num * 24 * 60, err=None)
    elif unit == 'h':
        return Result(ok=True, value=num * 60, err=None)
    else:
        return Result(ok=True, value=num, err=None)

