import re

def parse_window(spec):
    if not spec:
        return Result(ok=False, value=None, err='E_EMPTY')

    match = re.match(r'^(\d+)([a-z])$', spec)
    if not match:
        return Result(ok=False, value=None, err='E_RANGE')

    num = int(match.group(1))
    unit = match.group(2)

    if num < 1:
        return Result(ok=False, value=None, err='E_RANGE')

    if unit not in ('d', 'h', 'm'):
        return Result(ok=False, value=None, err='E_RANGE')

    if unit == 'd':
        minutes = num * 24 * 60
    elif unit == 'h':
        minutes = num * 60
    else:  # unit == 'm'
        minutes = num

    return Result(ok=True, value=minutes, err=None)
